derive_three_vars <- function(type_var, owned_var, rented_var) {
  n <- length(type_var)
  result <- rep(-3, n)

  for (i in seq_len(n)) {
    t <- type_var[i]
    o <- owned_var[i]
    r <- rented_var[i]

    # Map type missing codes
    t_std <- -3
    if (!is.na(t)) {
      if (t == -999) t_std <- -3
      else if (t == -92) t_std <- -9
      else if (t == -91) t_std <- -1
      else if (t == -1) t_std <- -8
      else if (t == 6) t_std <- -3  # Not to be asked -> Not asked
      else if (t %in% c(1, 2, 3)) t_std <- as.integer(t)
    }

    # Map owned subtype missing codes
    o_std <- -3
    if (!is.na(o)) {
      if (o == -999) o_std <- -3
      else if (o == -92) o_std <- -9
      else if (o == -91) o_std <- -1
      else if (o == -1) o_std <- -8
      else if (o %in% c(1, 2, 3, 4)) o_std <- as.integer(o)
      else o_std <- -3
    }

    # Map rented subtype missing codes
    r_std <- -3
    if (!is.na(r)) {
      if (r == -999) r_std <- -3
      else if (r == -92) r_std <- -9
      else if (r == -91) r_std <- -1
      else if (r == -1) r_std <- -8
      else if (r %in% c(1, 2, 3, 4, 5)) r_std <- as.integer(r)
      else r_std <- -3
    }

    if (t_std == 1) {
      # Owned
      if (o_std >= 1 && o_std <= 8) {
        result[i] <- o_std
      } else {
        result[i] <- o_std  # Preserve specific missing code from subtype
      }
    } else if (t_std == 2) {
      # Rented
      if (r_std >= 1 && r_std <= 8) {
        result[i] <- r_std
      } else {
        result[i] <- r_std  # Preserve specific missing code from subtype
      }
    } else if (t_std == 3) {
      # Something else -> category 8
      result[i] <- 8
    } else {
      # No substantive path fires, preserve specific missing from subtype
      # Check owned first (priority), then rented
      if (o_std != -3 && !is.na(o_std)) {
        result[i] <- o_std
      } else if (r_std != -3 && !is.na(r_std)) {
        result[i] <- r_std
